def eulerian_num(n, m):
    if m == 0:
        return 1
    if m == n:
        return 0
    if m == n - 1:
        return 1

    # Memoization table to store already computed values
    memo = {}

    def compute_eulerian(num, desc):
        if (num, desc) in memo:
            return memo[(num, desc)]

        if desc == 0:
            result = 1
        elif desc == num:
            result = 0
        elif desc == num - 1:
            result = 1
        else:
            result = compute_eulerian(num-1, desc) + (desc + 1) * compute_eulerian(num-1, desc-1)

        memo[(num, desc)] = result
        return result

    return compute_eulerian(n, m)

