def trim_tuple(tuples_list, k):
    if not isinstance(tuples_list, list) or not all(isinstance(t, tuple) for t in tuples_list):
        raise ValueError("The first argument must be a list of tuples")

    if not isinstance(k, int) or k < 0:
        raise ValueError("The second argument must be a non-negative integer")

    trimmed_tuples = []
    for t in tuples_list:
        if len(t) > k:
            trimmed_tuples.append(t[k:])
        else:
            trimmed_tuples.append(t)

    return str(trimmed_tuples).replace("'", "")

