def max_product(arr):
    if not arr:
        return 0

    max_product = 0
    current_product = 1
    increasing_start = 0

    for i in range(1, len(arr)):
        if arr[i] > arr[i - 1]:
            if arr[i] >= arr[increasing_start] or arr[i - 1] == arr[increasing_start]:
                current_product *= arr[i]
                if current_product > max_product:
                    max_product = current_product
            else:
                increasing_start = i
                current_product = arr[i]
        else:
            if current_product > max_product:
                max_product = current_product
            current_product = 1
            increasing_start = i

    if current_product > max_product:
        max_product = current_product

    if max_product == 0:
        return max(arr)

    return max_product

